COMMENT ON TABLE ELET_USR.ANAGRAFICA_SEGGIO IS 'Nella tabella verranno caricate le informazioni anagrafiche dei componenti dei seggi. Questo perchè eventuali modifiche anagrafiche o inserimenti di soggetti non devono impattare sulla tabella di Anagrafe';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_SEGGIO.ID IS 'Identificativo tabella';

