COMMENT ON COLUMN ELET_USR.ANAGRAFICA_SEGGIO.DATA_NASCITA IS 'Data Nascitsa  Componente Seggio';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_SEGGIO.RUOLO_SEGGIO IS 'Ruolo all''interno del seggio, gestisto come enumtype (PRESIDENTE, SEGRETARIO...)';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_SEGGIO.SESSO IS 'Sesso Componente Seggio';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_SEGGIO.COMUNE_RESIDENZA IS 'Descrizione Comune Residenza';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_SEGGIO.INDIRIZZO_RESIDENZA IS 'Indirizzo e civico residenza';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_SEGGIO.COMUNE_NASCITA IS 'Descrizione Comune Nascita';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_SEGGIO.CAP IS 'Cap di residenza';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_SEGGIO.ID_SOGGETTO IS 'Riferimento alla tabella Soggetti di Anagrafe, null o 0 se non residente';



