CREATE OR REPLACE TRIGGER ELET_USR.AUT_VOTO_PROG_TRG
   BEFORE INSERT
   ON ELET_USR.PRATICA_AUTORIZZAZIONE_VOTO
   FOR EACH ROW
DECLARE
    v_tipodoc VARCHAR2(10);

BEGIN

    SELECT cav.tipo_documento INTO v_tipodoc
    FROM conf_autorizzazione_voto cav
    WHERE cav.id_conf_autorizzazione_voto = :new.id_tipo_autorizzazione;

    IF v_tipodoc = 'L40'
    THEN
        :new.progressivo := AUT_VOTO_PROG_L40_SQ.NEXTVAL;

    ELSIF v_tipodoc = 'A40'
    THEN
        :new.progressivo := AUT_VOTO_PROG_A40_SQ.NEXTVAL;

    ELSIF v_tipodoc = 'AVOSP'
    THEN
        :new.progressivo := AUT_VOTO_PROG_AVOSP_SQ.NEXTVAL;

    ELSIF v_tipodoc = 'AVM'
    THEN
        :new.progressivo := AUT_VOTO_PROG_AVM_SQ.NEXTVAL;

    ELSIF v_tipodoc = 'AVS'
    THEN
        :new.progressivo := AUT_VOTO_PROG_AVS_SQ.NEXTVAL;

    ELSIF v_tipodoc = 'AVFR'
    THEN
        :new.progressivo := AUT_VOTO_PROG_AVFR_SQ.NEXTVAL;

    ELSIF v_tipodoc = 'AS'
    THEN
        :new.progressivo := AUT_VOTO_PROG_AS_SQ.NEXTVAL;
    END IF;

END;
/


