COMMENT ON TABLE ELET_USR.VOTI_SEGGI IS 'Contiente i voti registrati in un seggio durante una giornata elettorale';

COMMENT ON COLUMN ELET_USR.VOTI_SEGGI.ID_VOTI_SEGGIO IS 'Identificativo dei voti registrati nel seggio';

COMMENT ON COLUMN ELET_USR.VOTI_SEGGI.ID_SPECIFICA_EVENTO IS 'Identificativo della specifica evento';

COMMENT ON COLUMN ELET_USR.VOTI_SEGGI.ID_SEZIONE IS 'Identificativo della sezione';

COMMENT ON COLUMN ELET_USR.VOTI_SEGGI.SCHEDE_BIANCHE IS 'Numero di schede bianche registrate';

COMMENT ON COLUMN ELET_USR.VOTI_SEGGI.SCHEDE_NULLE IS 'Numero di schede nulle registrate';

COMMENT ON COLUMN ELET_USR.VOTI_SEGGI.SCHEDE_CONTESTATE IS 'Numero di schede contestate registrate';

COMMENT ON COLUMN ELET_USR.VOTI_SEGGI.DATA_CREAZIONE IS 'Data di creazione del record';

COMMENT ON COLUMN ELET_USR.VOTI_SEGGI.DATA_MODIFICA IS 'Data di ultima modifica del record';

COMMENT ON COLUMN ELET_USR.VOTI_SEGGI.SCHEDE_SI_REFERENDUM IS 'Numero di schede aventi risposta positiva per un quesito di un referendum';

COMMENT ON COLUMN ELET_USR.VOTI_SEGGI.SCHEDE_NO_REFERENDUM IS 'Numero di schede aventi risposta negativa per un quesito di un referendum';

COMMENT ON COLUMN ELET_USR.VOTI_SEGGI.VOTI_TOT_LISTE IS 'Somma  totale di tutti i voti delle liste collegate (necessario al riepilogo voti)';

COMMENT ON COLUMN ELET_USR.VOTI_SEGGI.VOTI_TOT_CANDIDATI IS 'Ottenuto dalla somma di tutti i voti  dei candidati iPIù il  voto proveniente dalla lista a lui collegata
 (necessario al riepilogo voti';

COMMENT ON COLUMN ELET_USR.VOTI_SEGGI.VOTI_TOT_SOLO_CANDIDATI IS 'Ottenuto dalla somma di tutti i voti dei candidati che hanno preso il solo voto candidato (e non dalla lista)
 (necessario al riepilogo voti..
CASO SUPPLETIVE: somma di tutti i candidati';

COMMENT ON COLUMN ELET_USR.VOTI_SEGGI.FLG_RETTIFICA IS '1-> seggio confermato, possibile modifica tramite rettifica; 
0-> seggio inserito ma non confermato';



