COMMENT ON TABLE ELET_USR.ANAGRAFICA_ELETTORALE IS 'Nella tabella verranno caricate le informazioni anagrafiche dei componenti dei seggi. Questo perchè eventuali modifiche anagrafiche o inserimenti di soggetti non devono impattare sulla tabella di Anagrafe';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_ELETTORALE.ID IS 'Identificativo tabella';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_ELETTORALE.CF IS 'Codice Fiscale Componente Seggio';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_ELETTORALE.NOME IS 'Nome Componente Seggio';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_ELETTORALE.COGNOME IS 'Cognome Componente Seggio';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_ELETTORALE.DATA_NASCITA IS 'Data Nascitsa  Componente Seggio';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_ELETTORALE.TIPO_ENTITA IS 'Indica il tipo di anagrafica (es. Seggio, SottoscrittoriLista)';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_ELETTORALE.RUOLO_ENTITA IS 'Ruolo a secondo dell''entità, gestisto come enumtype (PRESIDENTE, SEGRETARIO...)';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_ELETTORALE.SESSO IS 'Sesso Componente Seggio';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_ELETTORALE.COMUNE_RESIDENZA IS 'Descrizione Comune Residenza';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_ELETTORALE.INDIRIZZO_RESIDENZA IS 'Indirizzo e civico residenza';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_ELETTORALE.COMUNE_NASCITA IS 'Descrizione Comune Nascita';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_ELETTORALE.CAP IS 'Cap di residenza';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_ELETTORALE.ID_SOGGETTO IS 'Riferimento alla tabella Soggetti di Anagrafe, null o 0 se non residente';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_ELETTORALE.TELEFONO_UFFICIO IS 'Riferimento del telefono ufficio del rappresentante comunale';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_ELETTORALE.TELEFONO_CASA IS 'Riferimento del telefono casa del rappresentante comunale';

COMMENT ON COLUMN ELET_USR.ANAGRAFICA_ELETTORALE.CELLULARE IS 'Riferimento del cellulare del rappresentante comunale';



