COMMENT ON TABLE ELET_USR.MD_APPLICATIONS IS 'This is the base table for application projects.  It holds the base information for applications associated with a database';

COMMENT ON COLUMN ELET_USR.MD_APPLICATIONS.ID IS 'Primary Key';

COMMENT ON COLUMN ELET_USR.MD_APPLICATIONS.NAME IS 'Name of the application suite  //OBJECTNAME';

COMMENT ON COLUMN ELET_USR.MD_APPLICATIONS.DESCRIPTION IS 'Overview of what the application does.';

COMMENT ON COLUMN ELET_USR.MD_APPLICATIONS.BASE_DIR IS 'This is the base src directory for the application.  It could be an svn checkout, a clearcase view or something similar';

COMMENT ON COLUMN ELET_USR.MD_APPLICATIONS.OUTPUT_DIR IS 'This is the output directory where the scanner will present the converted files, if there are converted or modified.';

